 {/* DP-DDR-20261010-03: same outlet rule as module-shell firstScreeningGap(); an input check, so it is evaluated before any run. */const on=id=>Boolean($(id)?.checked),research=$('coeffMode')?.value==='table'||on('weirOn')===on('oriOn')||on('riserOn')||on('pipeOn');add(research?'阻擋':'通過',T('出口型式適用正式篩選','Outlet type eligible for formal screening'),research?T('目前為研究檢視出口或係數設定；正式受限篩選僅限單一被動堰流或單一矩形開口（固定係數）。','Research-inspection outlet or coefficient setting; formal screening is limited to one passive weir or one rectangular opening with fixed coefficients.'):T('單一被動出口，固定係數。','Single passive outlet, fixed coefficient.'),'outletType',research?T('此出口型式不在 176 組驗證範圍內，受限篩選維持鎖定。','This outlet type is outside the 176-case validated scope; constrained screening stays locked.'):T('符合正式篩選的出口範圍。','Within the outlet scope of formal screening.'));}
