function go(key){const m={storage:['mod-storage','storageTable'],water:['mod-optimization','hallow'],waterLimit:['mod-optimization','hallow'],outflow:['mod-optimization','qallow'],outletSize:['mod-outlet',$('weirOn')?.checked?'bw':'ao'],free:['mod-outlet','freeDischarge'],drain:['mod-optimization','residualPct'],drainLimit:['mod-optimization','residualPct'],routing:['mod-routing','run'],outletType:['mod-outlet','weirOn']}[key]||[],id=m[1];window.DSSWorkspacePages?.openTarget(m[0]);setTimeout(()=>{const e=$(id);if(e){e.classList.add('diagnostic-focus');e.focus({preventScroll:true});e.scrollIntoView({behavior:'smooth',block:'center'});}},40);}
